-- Generated by include/generate_quality_sql.py. All transformations execute in DuckDB.
CREATE OR REPLACE MACRO title_case(v) AS array_to_string(list_transform(string_split(trim(v),' '),w->upper(left(w,1))||lower(substr(w,2))),' ');
CREATE OR REPLACE MACRO dq_check(n,d,s,f) AS struct_pack(check_name:=n,dimension:=d,severity:=s,failed:=coalesce(f,false));
CREATE TABLE IF NOT EXISTS elt_quality_rows(run_id VARCHAR,phase VARCHAR,source_file VARCHAR,source_row BIGINT,row_key VARCHAR,check_name VARCHAR,dimension VARCHAR,severity VARCHAR,failed BOOLEAN,checked_at TIMESTAMPTZ);
DELETE FROM elt_quality_rows WHERE run_id=(SELECT run_id FROM pipeline_context) AND phase='base';

CREATE TEMP TABLE customers_checks AS
SELECT *, [dq_check('customer_key_required','Completeness','Critical',trim(customer_id) = ''),
dq_check('customer_duplicate','Uniqueness','Warning',count(*) OVER (PARTITION BY upper(trim(customer_id))) > 1),
dq_check('customer_phone','Validity','Warning',NOT regexp_full_match(trim(phone), '[0-9]{10}')),
dq_check('customer_email','Validity','Warning',NOT regexp_full_match(trim(email), '[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}')),
dq_check('customer_pincode','Validity','Warning',NOT regexp_full_match(trim(pincode), '[0-9]{6}')),
dq_check('customer_loyalty_casing','Consistency','Warning',loyalty_tier <> title_case(upper(trim(loyalty_tier)))),
dq_check('customer_signup_date','Validity','Critical',try_cast(signup_date AS TIMESTAMPTZ) IS NULL),
dq_check('customer_future_signup','Timeliness','Critical',try_cast(signup_date AS TIMESTAMPTZ) > (SELECT checked_at FROM pipeline_context))] AS checks FROM
(SELECT rowid AS source_row,row_number() OVER (ORDER BY rowid) AS source_csv_row,* FROM raw_customers WHERE _run_id=(SELECT run_id FROM pipeline_context)) source;
INSERT INTO elt_quality_rows
SELECT _run_id,(SELECT phase FROM pipeline_context),_source_file,source_row,customer_id,
x.check_name,x.dimension,x.severity,x.failed,(SELECT checked_at FROM pipeline_context)
FROM customers_checks,unnest(checks) t(x);
CREATE TEMP TABLE incoming_customers AS
WITH flagged AS (SELECT *,list_transform(list_filter(checks,x->x.failed AND x.severity='Critical'),x->x.check_name) AS critical,
list_transform(list_filter(checks,x->x.failed AND x.severity='Warning'),x->x.check_name) AS warnings FROM customers_checks)
SELECT upper(trim(customer_id)) AS customer_id, title_case(full_name) AS full_name,
CASE WHEN contains(email,'@') THEN left(lower(trim(split_part(email,'@',1))),2)||'***@'||lower(trim(split_part(email,'@',2))) ELSE '***' END AS email,
CASE WHEN length(trim(phone))>4 THEN left(trim(phone),2)||repeat('*',length(trim(phone))-4)||right(trim(phone),2) ELSE '****' END AS phone,
title_case(city) AS city,title_case(area) AS area,trim(pincode) AS pincode,try_cast(signup_date AS DATE) AS signup_date,
upper(trim(loyalty_tier)) AS loyalty_tier,upper(trim(is_active)) AS is_active,
CASE WHEN len(critical)>0 THEN 'Critical' WHEN len(warnings)>0 THEN 'Warning' ELSE 'Passed' END AS dq_status,
array_to_string(critical,'; ') AS failure_reason,array_to_string(warnings,'; ') AS warning_reason,
source_csv_row AS _source_row,_source_file,_loaded_at,_run_id
FROM flagged QUALIFY row_number() OVER (PARTITION BY upper(trim(customer_id)) ORDER BY source_row)=1;
CREATE OR REPLACE TABLE stg_customers AS SELECT * FROM incoming_customers;

CREATE TEMP TABLE products_checks AS
SELECT *, [dq_check('product_key_required','Completeness','Critical',trim(product_id) = ''),
dq_check('product_duplicate','Uniqueness','Warning',count(*) OVER (PARTITION BY upper(trim(product_id))) > 1),
dq_check('product_category_required','Completeness','Critical',trim(category) = ''),
dq_check('product_mrp','Accuracy','Critical',NOT coalesce(isfinite(try_cast(mrp AS DOUBLE)) AND try_cast(mrp AS DOUBLE)>0, false)),
dq_check('product_cost_mrp','Accuracy','Critical',NOT coalesce(isfinite(try_cast(cost_price AS DOUBLE)) AND try_cast(cost_price AS DOUBLE)>=0 AND try_cast(cost_price AS DOUBLE)<=try_cast(mrp AS DOUBLE),false))] AS checks FROM
(SELECT rowid AS source_row,row_number() OVER (ORDER BY rowid) AS source_csv_row,* FROM raw_products WHERE _run_id=(SELECT run_id FROM pipeline_context)) source;
INSERT INTO elt_quality_rows
SELECT _run_id,(SELECT phase FROM pipeline_context),_source_file,source_row,product_id,
x.check_name,x.dimension,x.severity,x.failed,(SELECT checked_at FROM pipeline_context)
FROM products_checks,unnest(checks) t(x);
CREATE TEMP TABLE incoming_products AS
WITH flagged AS (SELECT *,list_transform(list_filter(checks,x->x.failed AND x.severity='Critical'),x->x.check_name) AS critical,
list_transform(list_filter(checks,x->x.failed AND x.severity='Warning'),x->x.check_name) AS warnings FROM products_checks)
SELECT upper(trim(product_id)) AS product_id,title_case(product_name) AS product_name,title_case(category) AS category,
title_case(sub_category) AS sub_category,title_case(brand) AS brand,try_cast(mrp AS DECIMAL(18,2)) AS mrp,
try_cast(cost_price AS DECIMAL(18,2)) AS cost_price,lower(trim(unit)) AS unit,try_cast(is_perishable AS BOOLEAN) AS is_perishable,try_cast(launch_date AS DATE) AS launch_date,
CASE WHEN len(critical)>0 THEN 'Critical' WHEN len(warnings)>0 THEN 'Warning' ELSE 'Passed' END AS dq_status,
array_to_string(critical,'; ') AS failure_reason,array_to_string(warnings,'; ') AS warning_reason,
source_csv_row AS _source_row,_source_file,_loaded_at,_run_id
FROM flagged QUALIFY row_number() OVER (PARTITION BY upper(trim(product_id)) ORDER BY source_row)=1;
CREATE OR REPLACE TABLE stg_products AS SELECT * FROM incoming_products;

CREATE TEMP TABLE stores_checks AS
SELECT *, [dq_check('store_key_required','Completeness','Critical',trim(store_id) = ''),
dq_check('store_duplicate','Uniqueness','Warning',count(*) OVER (PARTITION BY upper(trim(store_id))) > 1),
dq_check('store_zone','Validity','Critical',upper(trim(zone)) NOT IN ('NORTH','SOUTH','EAST','WEST')),
dq_check('store_capacity','Accuracy','Critical',NOT coalesce(isfinite(try_cast(capacity_orders_per_day AS DOUBLE)) AND try_cast(capacity_orders_per_day AS DOUBLE)>0 AND try_cast(capacity_orders_per_day AS DOUBLE)%1=0,false)),
dq_check('store_manager','Completeness','Warning',trim(manager_name) = ''),
dq_check('store_pincode','Validity','Warning',NOT regexp_full_match(trim(pincode),'[0-9]{6}'))] AS checks FROM
(SELECT rowid AS source_row,row_number() OVER (ORDER BY rowid) AS source_csv_row,* FROM raw_stores WHERE _run_id=(SELECT run_id FROM pipeline_context)) source;
INSERT INTO elt_quality_rows
SELECT _run_id,(SELECT phase FROM pipeline_context),_source_file,source_row,store_id,
x.check_name,x.dimension,x.severity,x.failed,(SELECT checked_at FROM pipeline_context)
FROM stores_checks,unnest(checks) t(x);
CREATE TEMP TABLE incoming_stores AS
WITH flagged AS (SELECT *,list_transform(list_filter(checks,x->x.failed AND x.severity='Critical'),x->x.check_name) AS critical,
list_transform(list_filter(checks,x->x.failed AND x.severity='Warning'),x->x.check_name) AS warnings FROM stores_checks)
SELECT upper(trim(store_id)) AS store_id,title_case(store_name) AS store_name,title_case(zone) AS zone,title_case(area) AS area,
trim(pincode) AS pincode,try_cast(open_date AS DATE) AS open_date,title_case(manager_name) AS manager_name,try_cast(capacity_orders_per_day AS BIGINT) AS capacity_orders_per_day,
CASE WHEN len(critical)>0 THEN 'Critical' WHEN len(warnings)>0 THEN 'Warning' ELSE 'Passed' END AS dq_status,
array_to_string(critical,'; ') AS failure_reason,array_to_string(warnings,'; ') AS warning_reason,
source_csv_row AS _source_row,_source_file,_loaded_at,_run_id
FROM flagged QUALIFY row_number() OVER (PARTITION BY upper(trim(store_id)) ORDER BY source_row)=1;
CREATE OR REPLACE TABLE stg_stores AS SELECT * FROM incoming_stores;

CREATE TEMP TABLE payments_checks AS
SELECT *, [dq_check('payment_key_required','Completeness','Critical',trim(payment_id) = ''),
dq_check('payment_duplicate','Uniqueness','Critical',count(*) OVER (PARTITION BY upper(trim(payment_id))) > 1),
dq_check('payment_order_key','Consistency','Critical',NOT EXISTS (SELECT 1 FROM raw_orders o WHERE o._run_id=source._run_id AND upper(trim(o.order_id))=upper(trim(source.order_id)))),
dq_check('payment_mode','Validity','Critical',upper(trim(payment_mode)) NOT IN ('UPI','CARD','CASH ON DELIVERY','WALLET')),
dq_check('payment_status','Validity','Critical',upper(trim(payment_status)) NOT IN ('SUCCESS','FAILED','REFUNDED')),
dq_check('payment_amount','Accuracy','Critical',NOT coalesce(isfinite(try_cast(amount_paid AS DOUBLE)) AND try_cast(amount_paid AS DOUBLE)>=0,false)),
dq_check('payment_timestamp','Validity','Critical',try_cast(payment_ts AS TIMESTAMPTZ) IS NULL)] AS checks FROM
(SELECT rowid AS source_row,row_number() OVER (ORDER BY rowid) AS source_csv_row,* FROM raw_payments WHERE _run_id=(SELECT run_id FROM pipeline_context)) source;
INSERT INTO elt_quality_rows
SELECT _run_id,(SELECT phase FROM pipeline_context),_source_file,source_row,payment_id,
x.check_name,x.dimension,x.severity,x.failed,(SELECT checked_at FROM pipeline_context)
FROM payments_checks,unnest(checks) t(x);
CREATE TEMP TABLE incoming_payments AS
WITH flagged AS (SELECT *,list_transform(list_filter(checks,x->x.failed AND x.severity='Critical'),x->x.check_name) AS critical,
list_transform(list_filter(checks,x->x.failed AND x.severity='Warning'),x->x.check_name) AS warnings FROM payments_checks)
SELECT upper(trim(payment_id)) AS payment_id,upper(trim(order_id)) AS order_id,try_cast(payment_ts AS TIMESTAMPTZ) AS payment_ts,
upper(trim(payment_mode)) AS payment_mode,try_cast(amount_paid AS DECIMAL(18,2)) AS amount_paid,upper(trim(payment_status)) AS payment_status,trim(gateway_ref) AS gateway_ref,
CASE WHEN len(critical)>0 THEN 'Critical' WHEN len(warnings)>0 THEN 'Warning' ELSE 'Passed' END AS dq_status,
array_to_string(critical,'; ') AS failure_reason,array_to_string(warnings,'; ') AS warning_reason,
source_csv_row AS _source_row,_source_file,_loaded_at,_run_id
FROM flagged QUALIFY row_number() OVER (PARTITION BY upper(trim(payment_id)) ORDER BY source_row)=1;
CREATE OR REPLACE TABLE stg_payments AS SELECT * FROM incoming_payments;
CREATE OR REPLACE VIEW elt_quarantine AS
SELECT q.*,q.check_name AS failure_reason,to_json(r) AS raw_record FROM elt_quality_rows q JOIN raw_customers r ON q.source_row=r.rowid AND q.run_id=r._run_id AND q.source_file=r._source_file WHERE q.severity='Critical' AND q.failed
UNION ALL
SELECT q.*,q.check_name AS failure_reason,to_json(r) AS raw_record FROM elt_quality_rows q JOIN raw_products r ON q.source_row=r.rowid AND q.run_id=r._run_id AND q.source_file=r._source_file WHERE q.severity='Critical' AND q.failed
UNION ALL
SELECT q.*,q.check_name AS failure_reason,to_json(r) AS raw_record FROM elt_quality_rows q JOIN raw_stores r ON q.source_row=r.rowid AND q.run_id=r._run_id AND q.source_file=r._source_file WHERE q.severity='Critical' AND q.failed
UNION ALL
SELECT q.*,q.check_name AS failure_reason,to_json(r) AS raw_record FROM elt_quality_rows q JOIN raw_payments r ON q.source_row=r.rowid AND q.run_id=r._run_id AND q.source_file=r._source_file WHERE q.severity='Critical' AND q.failed
UNION ALL
SELECT q.*,q.check_name AS failure_reason,to_json(r) AS raw_record FROM elt_quality_rows q JOIN raw_orders r ON q.source_row=r.rowid AND q.run_id=r._run_id AND q.source_file=r._source_file WHERE q.severity='Critical' AND q.failed;
